import React from "react";
import { useEffect } from "react";
import HelpDocuments from "src/views/pages/ITSolutionDetails/ITSolutionResources/HelpDocuments";
import bgImg from "../../../assets/images/section1BgImg.png";
import bgImgSmall from "../../../assets/images/bannerSectionBgImgSmall.png";
import "../../../styles/animation.css";
import { Box } from "@mui/material";
import { useState } from "react";

const ITSolutionResourcesPage = () => {
  useEffect(() => {
    window.scrollTo(0, 0); // Scroll to the top when the component mounts
  }, []);
  const [backgroundPositionY, setBackgroundPositionY] = useState(0);
  //animation
  useEffect(() => {
    const handleScroll = () => {
      const offset = window.pageYOffset || document.documentElement.scrollTop;
      setBackgroundPositionY(offset); // Set the background position directly based on scroll offset
    };

    window.addEventListener("scroll", handleScroll);
    handleScroll(); // Initialize position

    return () => {
      window.removeEventListener("scroll", handleScroll);
    };
  }, []);
  return (
    <>
      <Box
        sx={{
          position: "relative",
          minHeight: "100vh",
          overflowX: "hidden",
          overflowY: "auto",
          scrollBehavior: "smooth",
          transition: "2s ease-in-out",
        }}
      >
        <Box
          sx={{
            backgroundImage: { xs: `url(${bgImgSmall})`, sm: `url(${bgImg})` },
            backgroundRepeat: "no-repeat",
            backgroundPosition: `right ${backgroundPositionY}px`,
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            zIndex: -1,
            pointerEvents: "none",
            transition: "background-position 1.5s ease-in-out",
          }}
        />
        <HelpDocuments />
      </Box>
    </>
  );
};

export default ITSolutionResourcesPage;
